def transform(grid):
    # Find the largest connected 2-shape and recolor it with the color of
    # the singleton 9 marker, leaving any other cells unchanged.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]==2 and (nx,ny) not in seen:
                            seen.add((nx,ny)); stack.append((nx,ny))
                comps.append(comp)
    if comps:
        target=max(comps,key=len)
        for r,c in target: out[r][c]=9
    return out

